var lvl=new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().First(l=>l.Name=="Level 2");
var rooms=new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Rooms).Cast<Autodesk.Revit.DB.Architecture.Room>().Where(r=>r.LevelId==lvl.Id).ToList();
var units=rooms.Where(r=>(r.get_Parameter(BuiltInParameter.ROOM_DEPARTMENT).AsString()??"").StartsWith("U")).GroupBy(r=>r.get_Parameter(BuiltInParameter.ROOM_DEPARTMENT).AsString())
 .Select(g=>new{unit=g.Key,internalM2=Math.Round(g.Where(r=>r.get_Parameter(BuiltInParameter.ROOM_NAME).AsString()!="Balcony").Sum(r=>r.Area)*0.09290304,1),balconyM2=Math.Round(g.Where(r=>r.get_Parameter(BuiltInParameter.ROOM_NAME).AsString()=="Balcony").Sum(r=>r.Area)*0.09290304,1),rooms=g.Count()}).OrderBy(u=>u.unit).ToList();
Func<BuiltInCategory,int> cnt=c=>new FilteredElementCollector(doc).OfCategory(c).WhereElementIsNotElementType().GetElementCount();
var stairs=new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Stairs).WhereElementIsNotElementType().OfClass(typeof(Autodesk.Revit.DB.Architecture.Stairs)).Cast<Element>().Select(s=>new{s.Id.IntegerValue,c=s.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).AsString()}).ToList();
var warn=doc.GetWarnings().GroupBy(w=>w.GetDescriptionText()).Select(g=>new{text=g.Key,n=g.Count(),ids=g.SelectMany(w=>w.GetFailingElements()).Select(i=>i.IntegerValue).Take(12).ToList()}).ToList();
return new{units,walls=cnt(BuiltInCategory.OST_Walls),doors=cnt(BuiltInCategory.OST_Doors),windows=cnt(BuiltInCategory.OST_Windows),floors=cnt(BuiltInCategory.OST_Floors),rooms=rooms.Count,railings=cnt(BuiltInCategory.OST_StairsRailing),stairs,warn};
